const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: `Bearer ${SK}` };
const {execSync} = require('child_process');

const cutoff = new Date(Date.now() - 4*60*60*1000).toISOString();
const res = await fetch(`${SUPA}/rest/v1/issues?status=in.(in_progress,in_review)&updated_at=lt.${cutoff}&select=task_key,title,assignee,status,updated_at&limit=20`, {headers:h});
const stuck = await res.json();
if (!stuck.length) return [{json:{action:'idle'}}];

const lines = stuck.map(i => {
  const hrs = Math.round((Date.now() - new Date(i.updated_at)) / 3600000);
  return `• [${i.task_key}] ${i.title.slice(0,50)} — ${i.assignee||'unassigned'} — ${hrs}h in ${i.status}`;
}).join('\n');

const msg = '⚠️ Blocked issues (>4h no activity):\n' + lines;
const esc = msg.replace(/'/g, "'\''");
try { execSync(`openclaw message send --channel telegram --target 5084875115 --message '${esc}' 2>/dev/null || true`); } catch(e) {}
return [{json:{action:'alerted', count: stuck.length}}];
